package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for OpenMapRealMatrix.setEntry
 */
public class OpenMapRealMatrix_setEntry_TriageGen2Test {

    private OpenMapRealMatrix matrix;
    private static final int ROWS = 5;
    private static final int COLS = 5;

    @Before
    public void setUp() {
        matrix = new OpenMapRealMatrix(ROWS, COLS);
    }

    @Test
    public void testSetEntry_PositiveValue() {
        int row = 1;
        int col = 2;
        double value = 10.5;

        matrix.setEntry(row, col, value);

        assertEquals("Value should be set correctly", value, matrix.getEntry(row, col), 1e-10);
    }

    @Test
    public void testSetEntry_NegativeValue() {
        int row = 0;
        int col = 0;
        double value = -5.5;

        matrix.setEntry(row, col, value);

        assertEquals("Negative value should be set correctly", value, matrix.getEntry(row, col), 1e-10);
    }

    @Test
    public void testSetEntry_ZeroValue_AddsEntry() {
        int row = 2;
        int col = 2;
        // First set a non-zero value to ensure it's in the map
        matrix.setEntry(row, col, 1.0);
        assertEquals(1.0, matrix.getEntry(row, col), 1e-10);

        // Now set to zero to trigger the removal branch
        matrix.setEntry(row, col, 0.0);

        assertEquals("Value should be 0.0 after setting to zero", 0.0, matrix.getEntry(row, col), 1e-10);
        // Note: Since we cannot directly check the internal 'entries' map size of OpenMapRealMatrix 
        // without reflection, we rely on the logic that 0.0 triggers the remove path.
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetEntry_InvalidRowIndex_TooHigh() {
        matrix.setEntry(ROWS, 0, 1.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetEntry_InvalidRowIndex_Negative() {
        matrix.setEntry(-1, 0, 1.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetEntry_InvalidColumnIndex_TooHigh() {
        matrix.setEntry(0, COLS, 1.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetEntry_InvalidColumnIndex_Negative() {
        matrix.setEntry(0, -1, 1.0);
    }

    @Test
    public void testSetEntry_OverwriteExistingValue() {
        int row = 3;
        int col = 3;
        matrix.setEntry(row, col, 1.0);
        matrix.setEntry(row, col, 2.0);

        assertEquals("Value should be overwritten", 2.0, matrix.getEntry(row, col), 1e-10);
    }
}
